sys_script_include.script:
var ValidationUtils = Class.create();

ValidationUtils.prototype = {

    initialize: function() {
    },

    /**
     * Check whether a value is empty.
     *
     * @param {String} value
     * @return {Boolean}
     */
    isEmpty: function(value) {

        return value === null ||
               value === undefined ||
               String(value).trim() === '';
    },

    /**
     * Check whether a value is not empty.
     *
     * @param {String} value
     * @return {Boolean}
     */
    isNotEmpty: function(value) {

        return !this.isEmpty(value);
    },

    /**
     * Validate whether a supplied value is numeric.
     *
     * @param {String|Number} value
     * @return {Boolean}
     */
    isNumber: function(value) {

        if (this.isEmpty(value)) {
            return false;
        }

        return !isNaN(value);
    },

    /**
     * Validate a non-negative whole number.
     *
     * @param {String|Number} value
     * @return {Boolean}
     */
    isNonNegativeInteger: function(value) {

        if (this.isEmpty(value)) {
            return false;
        }

        return /^\d+$/.test(String(value));
    },

    /**
     * Validate a basic email address format.
     *
     * @param {String} email
     * @return {Boolean}
     */
    isValidEmail: function(email) {

        if (this.isEmpty(email)) {
            return false;
        }

        var pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        return pattern.test(String(email).trim());
    },

    /**
     * Validate that a value does not exceed a maximum length.
     *
     * @param {String} value
     * @param {Number} maxLength
     * @return {Boolean}
     */
    isWithinMaxLength: function(value, maxLength) {

        if (this.isEmpty(value)) {
            return true;
        }

        return String(value).length <= maxLength;
    },

    type: 'ValidationUtils'
};
